=== FILE: axi4_lite_regs.v ===
// axi4_lite_regs.v
//
// AXI4-Lite subordinate with four 32-bit read/write registers.
// Implements interface_spec.md as planned in microarchitecture.md.
// Requirement: req-df40b5a460 "Create an AXI4-Lite register block."
//
// Handshake scheme (microarchitecture.md section 1): holding registers, no FSM.
//   awready = !aw_held && !bvalid
//   wready  = !w_held  && !bvalid
//   arready = !rvalid
// No READY depends combinationally on a VALID input.
//
// Register map (interface_spec.md section 3):
//   0x0 REG0, 0x4 REG1, 0x8 REG2, 0xC REG3, all R/W, reset 0x00000000.
// Unmapped (misaligned) addresses answer SLVERR (interface_spec.md section 5).

`default_nettype none

module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,

    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,

    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,

    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,

    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,

    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

    localparam integer STRB_WIDTH = DATA_WIDTH / 8;

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // Helper functions
    // ------------------------------------------------------------------

    // Byte-merge: copy each byte of new_word whose strobe bit is set,
    // keep the other bytes of old_word (microarchitecture.md section 3).
    function [DATA_WIDTH-1:0] merge;
        input [DATA_WIDTH-1:0] old_word;
        input [DATA_WIDTH-1:0] new_word;
        input [STRB_WIDTH-1:0] strb;
        integer b;
        begin
            merge = old_word;
            for (b = 0; b < STRB_WIDTH; b = b + 1) begin
                if (strb[b]) begin
                    merge[8*b +: 8] = new_word[8*b +: 8];
                end
            end
        end
    endfunction

    // Address decode (microarchitecture.md section 4): mapped when word
    // aligned and within the 16-byte window.
    function is_mapped;
        input [ADDR_WIDTH-1:0] addr;
        begin
            is_mapped = (addr[1:0] == 2'b00) &&
                        ((addr >> 4) == {ADDR_WIDTH{1'b0}});
        end
    endfunction

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------

    // Write side control
    reg                   aw_held;
    reg                   w_held;
    reg                   bvalid_q;
    reg  [1:0]            bresp_q;

    // Write holding registers (datapath, intentionally not reset;
    // their held flags are reset).
    reg  [ADDR_WIDTH-1:0] aw_addr_q;
    reg  [DATA_WIDTH-1:0] w_data_q;
    reg  [STRB_WIDTH-1:0] w_strb_q;

    // Read side
    reg                   rvalid_q;
    reg  [1:0]            rresp_q;
    reg  [DATA_WIDTH-1:0] rdata_q;

    // Register file: separate flops, no memory inference.
    reg  [DATA_WIDTH-1:0] reg0;
    reg  [DATA_WIDTH-1:0] reg1;
    reg  [DATA_WIDTH-1:0] reg2;
    reg  [DATA_WIDTH-1:0] reg3;

    // ------------------------------------------------------------------
    // Handshakes
    // ------------------------------------------------------------------

    wire awready_w = !aw_held && !bvalid_q;
    wire wready_w  = !w_held  && !bvalid_q;
    wire arready_w = !rvalid_q;

    wire aw_hs = s_axil_awvalid && awready_w;
    wire w_hs  = s_axil_wvalid  && wready_w;
    wire ar_hs = s_axil_arvalid && arready_w;

    // The write fires on the edge that completes the AW/W pair.
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    // Use the held copy when one exists, else the live bus.
    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [STRB_WIDTH-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    wire       wr_ok  = is_mapped(wr_addr);
    wire [1:0] wr_idx = wr_addr[3:2];

    wire       rd_ok  = is_mapped(s_axil_araddr);
    wire [1:0] rd_idx = s_axil_araddr[3:2];

    // Read mux (fully specified: no latch).
    reg  [DATA_WIDTH-1:0] rd_word;
    always @(*) begin
        case (rd_idx)
            2'd0:    rd_word = reg0;
            2'd1:    rd_word = reg1;
            2'd2:    rd_word = reg2;
            default: rd_word = reg3;
        endcase
    end

    // ------------------------------------------------------------------
    // Write holding registers
    // ------------------------------------------------------------------

    always @(posedge aclk) begin
        if (aw_hs) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Write control and B channel
    // ------------------------------------------------------------------

    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held  <= 1'b0;
            w_held   <= 1'b0;
            bvalid_q <= 1'b0;
            bresp_q  <= RESP_OKAY;
        end else if (do_write) begin
            // Both halves present: complete the write, raise B.
            aw_held  <= 1'b0;
            w_held   <= 1'b0;
            bvalid_q <= 1'b1;
            bresp_q  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
        end else begin
            if (aw_hs) begin
                aw_held <= 1'b1;
            end
            if (w_hs) begin
                w_held <= 1'b1;
            end
            if (bvalid_q && s_axil_bready) begin
                bvalid_q <= 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // Register file
    // ------------------------------------------------------------------

    always @(posedge aclk) begin
        if (!aresetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else if (do_write && wr_ok) begin
            case (wr_idx)
                2'd0:    reg0 <= merge(reg0, wr_data, wr_strb);
                2'd1:    reg1 <= merge(reg1, wr_data, wr_strb);
                2'd2:    reg2 <= merge(reg2, wr_data, wr_strb);
                default: reg3 <= merge(reg3, wr_data, wr_strb);
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Read channel
    // ------------------------------------------------------------------

    always @(posedge aclk) begin
        if (!aresetn) begin
            rvalid_q <= 1'b0;
            rresp_q  <= RESP_OKAY;
            rdata_q  <= {DATA_WIDTH{1'b0}};
        end else if (ar_hs) begin
            rvalid_q <= 1'b1;
            rresp_q  <= rd_ok ? RESP_OKAY : RESP_SLVERR;
            rdata_q  <= rd_ok ? rd_word : {DATA_WIDTH{1'b0}};
        end else if (rvalid_q && s_axil_rready) begin
            rvalid_q <= 1'b0;
        end
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------

    assign s_axil_awready = awready_w;
    assign s_axil_wready  = wready_w;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_arready = arready_w;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (microarchitecture.md section 7).
    // Not proven by this submission: no SymbiYosys job file accompanies it.
    // ------------------------------------------------------------------

    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    // Manager model: reset at start, VALIDs low in reset.
    always @(*) begin
        if (!f_past_valid) assume (!aresetn);
        if (!aresetn) begin
            assume (!s_axil_awvalid);
            assume (!s_axil_wvalid);
            assume (!s_axil_arvalid);
        end
    end

    // Manager model: VALID and payload held until READY.
    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready)) begin
                assume (s_axil_awvalid);
                assume ($stable(s_axil_awaddr));
            end
            if ($past(s_axil_wvalid && !s_axil_wready)) begin
                assume (s_axil_wvalid);
                assume ($stable(s_axil_wdata));
                assume ($stable(s_axil_wstrb));
            end
            if ($past(s_axil_arvalid && !s_axil_arready)) begin
                assume (s_axil_arvalid);
                assume ($stable(s_axil_araddr));
            end
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid) begin
            if (!$past(aresetn)) begin
                // Responses low and partial writes dropped after reset.
                assert (!bvalid_q);
                assert (!rvalid_q);
                assert (!aw_held);
                assert (!w_held);
            end else begin
                // B and R hold, with stable payload, until taken.
                if ($past(bvalid_q && !s_axil_bready)) begin
                    assert (bvalid_q);
                    assert ($stable(bresp_q));
                end
                if ($past(rvalid_q && !s_axil_rready)) begin
                    assert (rvalid_q);
                    assert ($stable(rresp_q));
                    assert ($stable(rdata_q));
                end
                // A response follows an accepted request one cycle later,
                // and never appears without one.
                if ($past(do_write)) assert (bvalid_q);
                if ($past(ar_hs)) assert (rvalid_q);
                if (!$past(do_write) && !$past(bvalid_q)) assert (!bvalid_q);
                if (!$past(ar_hs) && !$past(rvalid_q)) assert (!rvalid_q);
            end
        end
    end

    always @(*) begin
        if (f_past_valid) begin
            // At most one write request open.
            assert (!(aw_held && w_held));
            if (bvalid_q) assert (!aw_held && !w_held);
            // Response codes are OKAY or SLVERR only.
            assert ((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
            assert ((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
            if (rresp_q == RESP_SLVERR) assert (rdata_q == {DATA_WIDTH{1'b0}});
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && aresetn) begin
            cover (bvalid_q && s_axil_bready && (bresp_q == RESP_OKAY));
            cover (bvalid_q && s_axil_bready && (bresp_q == RESP_SLVERR));
            cover (rvalid_q && s_axil_rready && (rresp_q == RESP_OKAY));
            cover (rvalid_q && s_axil_rready && (rresp_q == RESP_SLVERR));
            cover (aw_held);
            cover (w_held);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
