// axi4_lite_regs_tb.v
//
// Self-checking directed testbench for axi4_lite_regs.
// Covers interface_spec.md section 8:
//   reset values; write then read of every register; wstrb partial writes;
//   AW before W, W before AW, both together; B and R backpressure;
//   back-to-back transactions; the SLVERR policy; the latency bound.
//
// Timing discipline: inputs change after the falling edge; handshakes and
// outputs are sampled 1 time unit before the rising edge.
// Every failed check is reported with $error; passing checks are counted.

`default_nettype none

`define CHECK(cond, msg) \
    begin \
        if (cond) begin \
            passed = passed + 1; \
        end else begin \
            failed = failed + 1; \
            $error msg ; \
        end \
    end

module axi4_lite_regs_tb;

    localparam integer ADDR_WIDTH = 4;
    localparam integer DATA_WIDTH = 32;
    localparam integer STRB_WIDTH = DATA_WIDTH / 8;
    localparam integer TIMEOUT    = 20;

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg                   aclk;
    reg                   aresetn;

    reg  [ADDR_WIDTH-1:0] s_axil_awaddr;
    reg                   s_axil_awvalid;
    wire                  s_axil_awready;

    reg  [DATA_WIDTH-1:0] s_axil_wdata;
    reg  [STRB_WIDTH-1:0] s_axil_wstrb;
    reg                   s_axil_wvalid;
    wire                  s_axil_wready;

    wire [1:0]            s_axil_bresp;
    wire                  s_axil_bvalid;
    reg                   s_axil_bready;

    reg  [ADDR_WIDTH-1:0] s_axil_araddr;
    reg                   s_axil_arvalid;
    wire                  s_axil_arready;

    wire [DATA_WIDTH-1:0] s_axil_rdata;
    wire [1:0]            s_axil_rresp;
    wire                  s_axil_rvalid;
    reg                   s_axil_rready;

    integer passed;
    integer failed;
    integer wr_accept_cycles;
    integer wr_latency;
    integer rd_accept_cycles;
    integer rd_latency;

    reg [8*64-1:0] nonce;

    axi4_lite_regs #(
        .ADDR_WIDTH(ADDR_WIDTH),
        .DATA_WIDTH(DATA_WIDTH)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready)
    );

    // Clock: posedges at 5, 15, 25, ...; negedges at 10, 20, ...
    initial aclk = 1'b0;
    always #5 aclk = ~aclk;

    // Advance from one falling edge, through the rising edge, to the next
    // falling edge.
    task tick;
        begin
            @(posedge aclk);
            @(negedge aclk);
        end
    endtask

    // ------------------------------------------------------------------
    // AXI4-Lite write. Called and returns at a falling edge.
    //   aw_dly / w_dly: cycles before AWVALID / WVALID are raised.
    //   b_dly: cycles (from request completion) before BREADY is raised.
    // ------------------------------------------------------------------
    task axi_write;
        input [ADDR_WIDTH-1:0] addr;
        input [DATA_WIDTH-1:0] data;
        input [STRB_WIDTH-1:0] strb;
        input integer          aw_dly;
        input integer          w_dly;
        input integer          b_dly;
        input [1:0]            exp_resp;
        integer   cyc;
        integer   lat;
        integer   bcyc;
        reg       aw_done;
        reg       w_done;
        reg       b_seen;
        reg       b_done;
        reg [1:0] b_first;
        begin
            aw_done = 1'b0;
            w_done  = 1'b0;
            cyc     = 0;
            while (!(aw_done && w_done) && (cyc < TIMEOUT)) begin
                s_axil_awaddr  = addr;
                s_axil_awvalid = !aw_done && (cyc >= aw_dly);
                s_axil_wdata   = data;
                s_axil_wstrb   = strb;
                s_axil_wvalid  = !w_done && (cyc >= w_dly);
                s_axil_bready  = 1'b0;
                #4;
                `CHECK(s_axil_bvalid === 1'b0,
                       ("write 0x%h: BVALID high before the request completed", addr))
                if (s_axil_awvalid && s_axil_awready) aw_done = 1'b1;
                if (s_axil_wvalid && s_axil_wready) w_done = 1'b1;
                tick;
                cyc = cyc + 1;
            end
            wr_accept_cycles = cyc;
            `CHECK(aw_done && w_done,
                   ("write 0x%h: AW/W not accepted within %0d cycles", addr, TIMEOUT))
            s_axil_awvalid = 1'b0;
            s_axil_wvalid  = 1'b0;

            lat     = 1;
            bcyc    = 0;
            b_seen  = 1'b0;
            b_done  = 1'b0;
            b_first = OKAY;
            while (!b_done && (bcyc < TIMEOUT)) begin
                s_axil_bready = (bcyc >= b_dly);
                #4;
                if (s_axil_bvalid) begin
                    if (!b_seen) begin
                        b_seen     = 1'b1;
                        wr_latency = lat;
                        b_first    = s_axil_bresp;
                        `CHECK(lat <= 2,
                               ("write 0x%h: latency %0d cycles exceeds the bound of 2", addr, lat))
                    end else begin
                        `CHECK(s_axil_bresp === b_first,
                               ("write 0x%h: BRESP changed while waiting for BREADY", addr))
                    end
                    `CHECK((s_axil_awready === 1'b0) && (s_axil_wready === 1'b0),
                           ("write 0x%h: AWREADY/WREADY high while a write response is pending", addr))
                    if (s_axil_bready) b_done = 1'b1;
                end else begin
                    if (b_seen) begin
                        failed = failed + 1;
                        $error("write 0x%h: BVALID dropped before the response was taken", addr);
                    end
                    lat = lat + 1;
                end
                tick;
                bcyc = bcyc + 1;
            end
            s_axil_bready = 1'b0;
            `CHECK(b_done,
                   ("write 0x%h: no write response within %0d cycles", addr, TIMEOUT))
            `CHECK(b_first === exp_resp,
                   ("write 0x%h: BRESP %b, expected %b", addr, b_first, exp_resp))
        end
    endtask

    // ------------------------------------------------------------------
    // AXI4-Lite read. Called and returns at a falling edge.
    //   ar_dly: cycles before ARVALID is raised.
    //   r_dly: cycles (from AR acceptance) before RREADY is raised.
    // ------------------------------------------------------------------
    task axi_read;
        input [ADDR_WIDTH-1:0] addr;
        input integer          ar_dly;
        input integer          r_dly;
        input [DATA_WIDTH-1:0] exp_data;
        input [1:0]            exp_resp;
        integer                cyc;
        integer                lat;
        integer                rcyc;
        reg                    ar_done;
        reg                    r_seen;
        reg                    r_done;
        reg [1:0]              r_resp_first;
        reg [DATA_WIDTH-1:0]   r_data_first;
        begin
            ar_done = 1'b0;
            cyc     = 0;
            while (!ar_done && (cyc < TIMEOUT)) begin
                s_axil_araddr  = addr;
                s_axil_arvalid = (cyc >= ar_dly);
                s_axil_rready  = 1'b0;
                #4;
                `CHECK(s_axil_rvalid === 1'b0,
                       ("read 0x%h: RVALID high before AR was accepted", addr))
                if (s_axil_arvalid && s_axil_arready) ar_done = 1'b1;
                tick;
                cyc = cyc + 1;
            end
            rd_accept_cycles = cyc;
            `CHECK(ar_done,
                   ("read 0x%h: AR not accepted within %0d cycles", addr, TIMEOUT))
            s_axil_arvalid = 1'b0;

            lat          = 1;
            rcyc         = 0;
            r_seen       = 1'b0;
            r_done       = 1'b0;
            r_resp_first = OKAY;
            r_data_first = {DATA_WIDTH{1'b0}};
            while (!r_done && (rcyc < TIMEOUT)) begin
                s_axil_rready = (rcyc >= r_dly);
                #4;
                if (s_axil_rvalid) begin
                    if (!r_seen) begin
                        r_seen       = 1'b1;
                        rd_latency   = lat;
                        r_resp_first = s_axil_rresp;
                        r_data_first = s_axil_rdata;
                        `CHECK(lat <= 2,
                               ("read 0x%h: latency %0d cycles exceeds the bound of 2", addr, lat))
                    end else begin
                        `CHECK((s_axil_rresp === r_resp_first) && (s_axil_rdata === r_data_first),
                               ("read 0x%h: RRESP/RDATA changed while waiting for RREADY", addr))
                    end
                    `CHECK(s_axil_arready === 1'b0,
                           ("read 0x%h: ARREADY high while read data is pending", addr))
                    if (s_axil_rready) r_done = 1'b1;
                end else begin
                    if (r_seen) begin
                        failed = failed + 1;
                        $error("read 0x%h: RVALID dropped before the data was taken", addr);
                    end
                    lat = lat + 1;
                end
                tick;
                rcyc = rcyc + 1;
            end
            s_axil_rready = 1'b0;
            `CHECK(r_done,
                   ("read 0x%h: no read data within %0d cycles", addr, TIMEOUT))
            `CHECK(r_resp_first === exp_resp,
                   ("read 0x%h: RRESP %b, expected %b", addr, r_resp_first, exp_resp))
            `CHECK(r_data_first === exp_data,
                   ("read 0x%h: RDATA 0x%h, expected 0x%h", addr, r_data_first, exp_data))
        end
    endtask

    // ------------------------------------------------------------------
    // Watchdog
    // ------------------------------------------------------------------
    initial begin
        #200000;
        failed = failed + 1;
        $error("watchdog: simulation did not finish in time");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        passed = 0;
        failed = 0;
        wr_accept_cycles = 0;
        wr_latency       = 0;
        rd_accept_cycles = 0;
        rd_latency       = 0;
        nonce = {64{8'h00}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {64{8'h00}};
        end

        aresetn        = 1'b0;
        s_axil_awaddr  = {ADDR_WIDTH{1'b0}};
        s_axil_awvalid = 1'b0;
        s_axil_wdata   = {DATA_WIDTH{1'b0}};
        s_axil_wstrb   = {STRB_WIDTH{1'b0}};
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b0;
        s_axil_araddr  = {ADDR_WIDTH{1'b0}};
        s_axil_arvalid = 1'b0;
        s_axil_rready  = 1'b0;

        // ---------------- Phase 1: reset ----------------
        $display("phase 1: reset values");
        @(negedge aclk);
        repeat (3) begin
            #4;
            `CHECK((s_axil_bvalid === 1'b0) && (s_axil_rvalid === 1'b0),
                   ("reset: BVALID/RVALID not low during reset"))
            tick;
        end
        aresetn = 1'b1;
        #4;
        `CHECK((s_axil_bvalid === 1'b0) && (s_axil_rvalid === 1'b0),
               ("reset: BVALID/RVALID not low after reset"))
        `CHECK((s_axil_awready === 1'b1) && (s_axil_wready === 1'b1) && (s_axil_arready === 1'b1),
               ("reset: AWREADY/WREADY/ARREADY not high after reset"))
        tick;
        axi_read(4'h0, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'h4, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'h8, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'hC, 0, 0, 32'h0000_0000, OKAY);

        // ---------------- Phase 2: write then read every register ----------------
        $display("phase 2: write then read every register");
        axi_write(4'h0, 32'h1122_3344, 4'hF, 0, 0, 0, OKAY);
        axi_write(4'h4, 32'h5566_7788, 4'hF, 0, 0, 0, OKAY);
        axi_write(4'h8, 32'h99AA_BBCC, 4'hF, 0, 0, 0, OKAY);
        axi_write(4'hC, 32'hDDEE_FF00, 4'hF, 0, 0, 0, OKAY);
        axi_read(4'h0, 0, 0, 32'h1122_3344, OKAY);
        axi_read(4'h4, 0, 0, 32'h5566_7788, OKAY);
        axi_read(4'h8, 0, 0, 32'h99AA_BBCC, OKAY);
        axi_read(4'hC, 0, 0, 32'hDDEE_FF00, OKAY);

        // ---------------- Phase 3: wstrb partial writes ----------------
        $display("phase 3: wstrb partial writes");
        axi_write(4'h0, 32'hAABB_CCDD, 4'b0101, 0, 0, 0, OKAY);
        axi_read(4'h0, 0, 0, 32'h11BB_33DD, OKAY);
        axi_write(4'h0, 32'h9900_0000, 4'b1000, 0, 0, 0, OKAY);
        axi_read(4'h0, 0, 0, 32'h99BB_33DD, OKAY);
        axi_write(4'h0, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0, OKAY);
        axi_read(4'h0, 0, 0, 32'h99BB_33DD, OKAY);
        axi_write(4'h0, 32'h0000_EE00, 4'b0010, 0, 0, 0, OKAY);
        axi_read(4'h0, 0, 0, 32'h99BB_EEDD, OKAY);

        // ---------------- Phase 4: AW/W ordering ----------------
        $display("phase 4: AW/W ordering");
        axi_write(4'h4, 32'h0BAD_F00D, 4'hF, 0, 3, 0, OKAY);   // AW before W
        axi_read(4'h4, 0, 0, 32'h0BAD_F00D, OKAY);
        axi_write(4'h8, 32'hC0FF_EE11, 4'hF, 2, 0, 0, OKAY);   // W before AW
        axi_read(4'h8, 0, 0, 32'hC0FF_EE11, OKAY);
        axi_write(4'hC, 32'h1234_5678, 4'hF, 0, 1, 0, OKAY);   // AW before W, gap 1
        axi_read(4'hC, 0, 0, 32'h1234_5678, OKAY);
        axi_write(4'hC, 32'h8765_4321, 4'hF, 1, 0, 0, OKAY);   // W before AW, gap 1
        axi_read(4'hC, 0, 0, 32'h8765_4321, OKAY);
        axi_write(4'h4, 32'hA5A5_A5A5, 4'hF, 2, 2, 0, OKAY);   // together, delayed
        axi_read(4'h4, 0, 0, 32'hA5A5_A5A5, OKAY);

        // ---------------- Phase 5: B and R backpressure ----------------
        $display("phase 5: B and R backpressure");
        axi_write(4'h8, 32'h1357_9BDF, 4'hF, 0, 0, 4, OKAY);
        axi_read(4'h8, 0, 3, 32'h1357_9BDF, OKAY);
        axi_read(4'h4, 2, 5, 32'hA5A5_A5A5, OKAY);
        axi_write(4'h6, 32'hFFFF_FFFF, 4'hF, 0, 0, 2, SLVERR);
        axi_read(4'h4, 0, 2, 32'hA5A5_A5A5, OKAY);

        // ---------------- Phase 6: back-to-back ----------------
        $display("phase 6: back-to-back transactions");
        axi_write(4'h0, 32'h0000_0001, 4'hF, 0, 0, 0, OKAY);
        axi_write(4'h4, 32'h0000_0002, 4'hF, 0, 0, 0, OKAY);
        `CHECK(wr_accept_cycles == 1,
               ("back-to-back write 2 accepted after %0d cycles, expected 1", wr_accept_cycles))
        axi_write(4'h8, 32'h0000_0003, 4'hF, 0, 0, 0, OKAY);
        `CHECK(wr_accept_cycles == 1,
               ("back-to-back write 3 accepted after %0d cycles, expected 1", wr_accept_cycles))
        axi_write(4'hC, 32'h0000_0004, 4'hF, 0, 0, 0, OKAY);
        `CHECK(wr_accept_cycles == 1,
               ("back-to-back write 4 accepted after %0d cycles, expected 1", wr_accept_cycles))
        axi_read(4'h0, 0, 0, 32'h0000_0001, OKAY);
        axi_read(4'h4, 0, 0, 32'h0000_0002, OKAY);
        `CHECK(rd_accept_cycles == 1,
               ("back-to-back read 2 accepted after %0d cycles, expected 1", rd_accept_cycles))
        axi_read(4'h8, 0, 0, 32'h0000_0003, OKAY);
        `CHECK(rd_accept_cycles == 1,
               ("back-to-back read 3 accepted after %0d cycles, expected 1", rd_accept_cycles))
        axi_read(4'hC, 0, 0, 32'h0000_0004, OKAY);
        `CHECK(rd_accept_cycles == 1,
               ("back-to-back read 4 accepted after %0d cycles, expected 1", rd_accept_cycles))

        // ---------------- Phase 7: SLVERR policy ----------------
        $display("phase 7: SLVERR policy");
        axi_write(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 0, SLVERR);
        axi_read(4'h4, 0, 0, 32'h0000_0002, OKAY);
        axi_write(4'hE, 32'hFFFF_FFFF, 4'hF, 0, 0, 0, SLVERR);
        axi_read(4'hC, 0, 0, 32'h0000_0004, OKAY);
        axi_write(4'h1, 32'hFFFF_FFFF, 4'hF, 1, 0, 0, SLVERR);
        axi_read(4'h0, 0, 0, 32'h0000_0001, OKAY);
        axi_read(4'h5, 0, 0, 32'h0000_0000, SLVERR);
        axi_read(4'h2, 0, 0, 32'h0000_0000, SLVERR);
        axi_read(4'hF, 0, 1, 32'h0000_0000, SLVERR);
        axi_read(4'hB, 0, 0, 32'h0000_0000, SLVERR);
        axi_read(4'h8, 0, 0, 32'h0000_0003, OKAY);

        // ---------------- Phase 8: concurrent read and write ----------------
        $display("phase 8: concurrent read and write");
        fork
            axi_write(4'h0, 32'hFEED_FACE, 4'hF, 0, 1, 2, OKAY);
            axi_read(4'h8, 0, 1, 32'h0000_0003, OKAY);
        join
        axi_read(4'h0, 0, 0, 32'hFEED_FACE, OKAY);

        // ---------------- Phase 9: reset with work in flight ----------------
        $display("phase 9: reset with a half-accepted write and pending read");
        s_axil_awaddr  = 4'h0;
        s_axil_awvalid = 1'b1;
        s_axil_wvalid  = 1'b0;
        s_axil_araddr  = 4'h4;
        s_axil_arvalid = 1'b1;
        s_axil_bready  = 1'b0;
        s_axil_rready  = 1'b0;
        #4;
        `CHECK((s_axil_awready === 1'b1) && (s_axil_arready === 1'b1),
               ("reset test: AWREADY/ARREADY not high before issuing AW and AR"))
        tick;
        s_axil_awvalid = 1'b0;
        s_axil_arvalid = 1'b0;
        #4;
        `CHECK(s_axil_rvalid === 1'b1,
               ("reset test: read data not pending before reset"))
        `CHECK((s_axil_awready === 1'b0) && (s_axil_wready === 1'b1) && (s_axil_bvalid === 1'b0),
               ("reset test: AW not held, waiting for W, before reset"))
        tick;
        aresetn = 1'b0;
        #4;
        tick;
        #4;
        `CHECK((s_axil_bvalid === 1'b0) && (s_axil_rvalid === 1'b0),
               ("reset test: BVALID/RVALID not low during reset"))
        `CHECK((s_axil_awready === 1'b1) && (s_axil_wready === 1'b1) && (s_axil_arready === 1'b1),
               ("reset test: half-accepted write or pending read not discarded by reset"))
        tick;
        aresetn = 1'b1;
        #4;
        `CHECK((s_axil_bvalid === 1'b0) && (s_axil_rvalid === 1'b0),
               ("reset test: BVALID/RVALID not low after reset"))
        tick;
        axi_read(4'h0, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'h4, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'h8, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'hC, 0, 0, 32'h0000_0000, OKAY);

        // W alone after reset must not complete a write with the discarded AW.
        s_axil_wdata  = 32'hDEAD_0000;
        s_axil_wstrb  = 4'hF;
        s_axil_wvalid = 1'b1;
        #4;
        `CHECK(s_axil_wready === 1'b1,
               ("reset test: WREADY not high for W after reset"))
        tick;
        s_axil_wvalid = 1'b0;
        #4;
        `CHECK(s_axil_bvalid === 1'b0,
               ("reset test: write completed using an AW that reset should have discarded"))
        tick;
        #4;
        `CHECK(s_axil_bvalid === 1'b0,
               ("reset test: write response without a write address"))
        tick;
        s_axil_awaddr  = 4'hC;
        s_axil_awvalid = 1'b1;
        #4;
        `CHECK(s_axil_awready === 1'b1,
               ("reset test: AWREADY not high to complete the held W"))
        tick;
        s_axil_awvalid = 1'b0;
        s_axil_bready  = 1'b1;
        #4;
        `CHECK((s_axil_bvalid === 1'b1) && (s_axil_bresp === OKAY),
               ("reset test: no OKAY response one cycle after the W-then-AW write completed"))
        tick;
        s_axil_bready = 1'b0;
        axi_read(4'hC, 0, 0, 32'hDEAD_0000, OKAY);
        axi_read(4'h0, 0, 0, 32'h0000_0000, OKAY);

        // ---------------- Verdict ----------------
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`undef CHECK

`default_nettype wire
